description:
Write a function that deeply merges two objects. Properties from the second object overwrite the first. Nested objects should be merged recursively, not replaced.

Example:
- Input: { a: 1, b: { x: 1 } }, { b: { y: 2 }, c: 3 }
- Output: { a: 1, b: { x: 1, y: 2 }, c: 3 }

starterCode:
function deepMerge(obj1, obj2) {
  // your code here
}

solutionCode:
function deepMerge(obj1, obj2) {
  const result = { ...obj1 };
  for (const key of Object.keys(obj2)) {
    if (
      obj2[key] && typeof obj2[key] === 'object' && !Array.isArray(obj2[key]) &&
      result[key] && typeof result[key] === 'object' && !Array.isArray(result[key])
    ) {
      result[key] = deepMerge(result[key], obj2[key]);
    } else {
      result[key] = obj2[key];
    }
  }
  return result;
}
